// _nested_clonePtrExternalProof returns a pointer to a copy of the value that
// x, a *external.Proof, points at, and nil for a nil x.
func _nested_clonePtrExternalProof(x *external.Proof) *external.Proof {
	if x == nil {
		return nil
	}
	return x.CloneKanon()
}
